import * as React from 'react';
import QRCode from 'qrcode';
import { cn } from '@/lib/utils';

interface QrCodeProps {
  /** The text to encode. Keep it short: QR capacity drops fast above ~100 chars. */
  value: string;
  size?: number;
  className?: string;
  /** Rendered under the code, e.g. the member code itself. */
  caption?: string;
  label?: string;
}

/**
 * Renders a QR code to a canvas.
 *
 * Drawn on the client rather than generated by the server: the payload is not
 * secret (it is the member code already printed on the card) and generating it
 * here keeps the image crisp at any size and available offline.
 *
 * `margin` is 2 rather than 0 because scanners need the quiet zone around the
 * code; without it many phone cameras refuse to lock on.
 */
export function QrCode({ value, size = 160, className, caption, label }: QrCodeProps) {
  const canvasRef = React.useRef<HTMLCanvasElement | null>(null);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    let cancelled = false;

    QRCode.toCanvas(canvas, value, {
      width: size,
      margin: 2,
      errorCorrectionLevel: 'M',
      color: { dark: '#0b1020', light: '#ffffff' },
    }).catch((err: unknown) => {
      // The canvas stays blank; the code is also printed as text below it, so
      // the officer can still type the member code by hand.
      if (!cancelled) setError(err instanceof Error ? err.message : 'Gagal membuat kode QR.');
    });

    return () => {
      cancelled = true;
    };
  }, [value, size]);

  return (
    <figure className={cn('flex flex-col items-center gap-2', className)}>
      <div className="rounded-xl border border-border bg-white p-2 shadow-sm">
        <canvas
          ref={canvasRef}
          width={size}
          height={size}
          role="img"
          aria-label={label ?? `Kode QR untuk ${value}`}
          className="block"
        />
      </div>
      {caption ? (
        <figcaption className="font-mono text-xs font-semibold tracking-wider text-foreground">
          {caption}
        </figcaption>
      ) : null}
      {error ? (
        <p className="text-2xs text-destructive" role="alert">
          {error}
        </p>
      ) : null}
    </figure>
  );
}
